#include "common/airi_text.h"
#include <algorithm>
#include <cctype>
#include <iomanip>
#include <sstream>
namespace airi::text {std::string sanitize_filename_utf8(std::string name){if(name.empty())return "download.bin";const std::string bad="<>:\"/\\|?*";for(char&c:name)if(static_cast<unsigned char>(c)<32||bad.find(c)!=std::string::npos)c='_';while(!name.empty()&&(name.back()==' '||name.back()=='.'))name.pop_back();if(name.empty()||name=="."||name=="..")return "download.bin";static const char* reserved[]={"CON","PRN","AUX","NUL","COM1","COM2","COM3","COM4","COM5","COM6","COM7","COM8","COM9","LPT1","LPT2","LPT3","LPT4","LPT5","LPT6","LPT7","LPT8","LPT9"};std::string stem=name.substr(0,name.find('.')),upper=stem;std::transform(upper.begin(),upper.end(),upper.begin(),[](unsigned char c){return static_cast<char>(std::toupper(c));});for(auto*r:reserved)if(upper==r)return "_"+name;return name;}std::string filename_from_url_utf8(const std::string& url){auto end=url.find_first_of("?#");std::string clean=url.substr(0,end);auto slash=clean.find_last_of('/');std::string name=slash==std::string::npos?clean:clean.substr(slash+1);if(name.empty())name="download.bin";return sanitize_filename_utf8(name);}std::string human_bytes(unsigned long long bytes){static const char* units[]={"B","KB","MB","GB","TB","PB"};double n=static_cast<double>(bytes);int u=0;while(n>=1024.0&&u<5){n/=1024.0;++u;}std::ostringstream os;if(!u)os<<static_cast<unsigned long long>(n);else os<<std::fixed<<std::setprecision(n>=100?0:n>=10?1:2)<<n;os<<' '<<units[u];return os.str();}std::string lower_ascii(std::string s){std::transform(s.begin(),s.end(),s.begin(),[](unsigned char c){return static_cast<char>(std::tolower(c));});return s;}}
